Translate("deDE", "ragefire-chasm", {
	title = "Ragefireabgrund",
	aliases = { "Ragefire" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Ragefireabgrund ist ein Netz brennender Höhlen unter {link:orgrimmar}Orgrimmar{/link}. Lavaströme erhellen seine Tunnel, und die Hitze der Tiefe steigt durch seinen Stein empor. Man erreicht ihn durch einen Gang am Grund der {link:cleft-of-shadow}Cleft of Shadow{/link}. Nur wenige Bürger der {link:capital-city}Hauptstadt{/link} wissen, was unter ihren Füßen liegt. Wer es weiß, hat Grund, es zu fürchten, denn der Abgrund ist die Heimat wilder {link:troggs}Troggs{/link} und eines geheimen Kults, der den Untergang der {link:horde}Horde{/link} plant.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer den Abgrund zuerst fand oder wie tief seine Tunnel reichen. Die {link:troggs}Troggs{/link} kamen zuerst. Sie stiegen aus den lavagefüllten Tiefen empor und nahmen die oberen Höhlen für sich in Besitz. Dann kam die Sengende Klinge aus der Stadt darüber herab, eine Sekte des {link:shadow-council}Schattenrats{/link} und eine Schwester der {link:burning-blade}Brennenden Klinge{/link}. Die Troggs waren zu schwach, um sie zu vertreiben, und beide teilen sich nun die Dunkelheit in unruhiger Feindschaft.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Sengende Klinge hat den Abgrund zu ihrem Heiligtum gemacht. Ihre Kultisten halten sich für die aufstrebende Generation der Kunst der Hexenmeister, und sie arbeiten daran, das treue Volk von {link:orgrimmar}Orgrimmar{/link} zur Dämonenanbetung zu bekehren. Drei Anführer befehligen sie: eine Teufelswache, {link:taragaman-the-hungerer}Taragaman der Hungernde{/link}, ein Hexenmeister, {link:jergosh-the-invoker}Jergosh der Beschwörer{/link}, und ein {link:satyrs}Satyr{/link}, {link:bazzalan}Bazzalan{/link}. Die {link:troggs}Troggs{/link} des Ragefireclans halten noch die Höhlen nahe dem Eingang unter ihrem Häuptling {link:oggleflint}Oggleflint{/link}.

Der Abgrund zieht die Blicke der ganzen {link:horde}Horde{/link} auf sich. Die Seherin der {link:tauren}Tauren{/link} {link:magatha-grimtotem}Magatha Grimtotem{/link} sandte Gesandte, um mit den Troggs Frieden zu schließen, und sie wurden erschlagen. Einer ihrer Diener, {link:maur-raincaller}Maur{/link} Grimtotem, stieg hinab, um mit ihnen zu sprechen, und kehrte nie zurück. Gesandte der {link:forsaken}Verlassenen{/link} wollen zwei Bücher dunkler Zauber, die die Kultisten besitzen. Vor allem aber wacht der Kriegshäuptling {link:thrall}Thrall{/link}. Der Hexenmeister {link:neeru-fireblade}Neeru Fireblade{/link} schickt Helden hinab in den Abgrund, und Thrall weiß genau, warum.]=],
		},
		{
			title = "Im Abgrund",
			text = [=[• {b}Die Trogghöhlen.{/b} Nahe dem Eingang leisten die {link:troggs}Troggs{/link} des Ragefireclans Widerstand. {link:oggleflint}Oggleflint{/link} herrscht über sie.
• {b}Die Lavabecken.{/b} Weiter drinnen öffnen sich die Tunnel auf Seen aus geschmolzenem Gestein, über denen geschmolzene Elementare durch das Feuer treiben und große Erdbohrer sich durch den Stein graben. Die Kultisten halten zwischen ihnen Wache.
• {b}Die Plattform des Hungernden.{/b} {link:taragaman-the-hungerer}Taragaman der Hungernde{/link} wartet über dem Feuer, der Anführer, den der Kult der Welt zeigt.
• {b}Die Kammer des Hexenmeisters.{/b} {link:jergosh-the-invoker}Jergosh der Beschwörer{/link} vollzieht seine Riten in einer Kammer der unteren Höhlen.
• {b}Der Sims des Satyrs.{/b} Oberhalb der Kammer des Hexenmeisters, auf einem Sims, den man über dunkle Rampen erreicht, wartet {link:bazzalan}Bazzalan{/link} im Schatten.]=],
		},
		{
			title = "Die Bewohner der Tiefe",
			text = [=[Die Sengende Klinge gliedert sich in Kultisten, Vollstrecker und Hexenmeister, jeder gefährlicher als der vorige. Der Leichnam von {link:maur-raincaller}Maur{/link} Grimtotem liegt irgendwo in den Tunneln und umklammert noch immer eine Tasche, die er nicht loslassen wollte. Die meisten Kultisten kennen die Wahrheit nicht: dass ihre wahren Herren oben sie nur als entbehrlich ansehen und dass nur zwei ihrer Anführer geschätzt werden.]=],
		},
	},
})

Translate("deDE", "taragaman-the-hungerer", {
	title = "Taragaman der Hungernde",
	subtitle = "Teufelswache der Sengenden Klinge",
	found = "Eine Plattform über der Lava, tief im Ragefireabgrund",
	hint = [=[Stellt Euch der Teufelswache, die über die Tiefen des Ragefireabgrunds herrscht.]=],
	allegiance = "Sengende Klinge · Brennende Legion",
	aliases = { "Taragaman" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Taragaman der Hungernde ist eine Teufelswache, ein dämonischer Krieger der {link:burning-legion}Brennenden Legion{/link}, der in den Tiefen des Ragefireabgrunds haust. Für die Kultisten der Sengenden Klinge ist er ihr Herr, und für die wenigen in {link:orgrimmar}Orgrimmar{/link}, die vom Abgrund wissen, ist er das Oberhaupt der Sekte. Von seiner Plattform über dem Feuer verbreitet er den Einfluss der Legion unter den Bürgern der Stadt darüber. Nur wenige, die hinabgestiegen sind, um sich ihm zu stellen, sind zurückgekehrt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Taragaman ist das Gesicht der Sengenden Klinge. Er ist auch ihre größte Lüge. Jene, die den Kult wirklich befehligen, haben ihn zu einem Köder gemacht, einem Dämon, der groß genug ist, um die treuen Diener des Kriegshäuptlings hinab in die Dunkelheit zu locken, wo sie sterben sollen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt die Sengende Klinge in den Augen ihrer Anhänger.
• Er arbeitet daran, das Volk von {link:orgrimmar}Orgrimmar{/link} mit dämonischem Einfluss zu verderben.
• Er wartet in den Tiefen auf jene, die ausgesandt werden, um ihn zu töten.
• Er verbirgt die wahren Anführer der Sekte hinter seinem eigenen furchterregenden Namen.]=],
		},
	},
	chapters = {
		{
			title = "Die Bestie erschlagen",
			hint = "Bringt Neeru Fireblade das Herz der Teufelswache.",
			text = [=[{link:neeru-fireblade}Neeru Fireblade{/link} nannte Taragaman den Anführer der Sengenden Klinge und verlangte sein Herz, damit der Kriegshäuptling zufrieden sei. Als ihm das Herz gebracht wurde, versprach er, sich angemessen darum zu kümmern und {link:thrall}Thrall{/link} von dem Sieg zu berichten. Doch Neeru hatte nichts aufgegeben, was ihm etwas wert war. Die Teufelswache war nur ein Köder, ein Dämon, der groß genug war, um Thralls Getreue in den Abgrund zu locken. Die wahren Anführer der Sekte lebten noch, und der Hexenmeister hoffte noch immer, sie zu behalten.]=],
		},
	},
	mentions = {
		{ text = "Die Bestie erschlagen" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "sandte Helden aus, um ihn zu erschlagen" },
		{ id = "jergosh-the-invoker", name = "Jergosh der Beschwörer", note = "ein Anführer derselben Sekte" },
		{ id = "bazzalan", name = "Bazzalan", note = "ein Anführer derselben Sekte" },
	},
})

