		{ id = "thrall", name = "Thrall", note = "befahl seinen Tod" },
	},
})

Translate("deDE", "bazzalan", {
	title = "Bazzalan",
	subtitle = "Satyr der Sengenden Klinge",
	found = [=[Ein Sims oberhalb der Kammer des Hexenmeisters im Ragefireabgrund]=],
	hint = [=[Durchsucht die dunklen Simse des Ragefireabgrunds nach einem Satyr.]=],
	allegiance = "Sengende Klinge · Schattenrat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bazzalan ist ein {link:satyrs}Satyr{/link}, eines der von Dämonen entstellten Wesen des alten {link:kalimdor}Kalimdor{/link}, der auf den oberen Simsen des Ragefireabgrunds lauert. Er ist flink, listig und tödlich mit der Klinge. Seine Beweggründe sind seine eigenen. Doch er und der Hexenmeister {link:jergosh-the-invoker}Jergosh{/link} sind die wahren Anführer der Sengenden Klinge, und die Herren des Kults schätzen ihn höher als die Teufelswache, die an seiner Stelle steht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Bazzalan ist eines der beiden verborgenen Häupter der Sengenden Klinge. Sein Tod ist ein Schlag, den der Kult nicht verbergen kann.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt die Sengende Klinge im {link:ragefire-chasm}Ragefireabgrund{/link} an der Seite von {link:jergosh-the-invoker}Jergosh{/link} dem Beschwörer an.
• Er hält sich im Schatten hoch über den unteren Höhlen auf.]=],
		},
	},
	mentions = {
		{ text = "Verborgene Feinde" },
