	allegiance = "Troggs der Ragefire",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oggleflint ist der Häuptling der {link:troggs}Troggs{/link} der {link:ragefire-chasm}Ragefire{/link}, roher Kreaturen, die aus den Lavatunneln unter {link:orgrimmar}Orgrimmar{/link} emporstiegen. Sein Volk herrschte einst allein über den Abgrund. Als die Sengende Klinge kam, konnten die Troggs sie nicht vertreiben, und sie zogen sich in die Höhlen nahe dem Eingang zurück. Dort warten sie darauf, dass die Eindringlinge gehen.]=],
